import hmac
import hashlib
import base64
import json
import time
import os
import secrets
from typing import Optional, Tuple, Dict, Any


class SecureTokenValidator:
    """Enterprise-grade token validation with defense-in-depth."""

    SUPPORTED_ALGORITHMS = frozenset(['HS256', 'HS384', 'HS512'])
    HASH_MAP = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
    }
    MAX_TOKEN_AGE = 3600
    MAX_CLOCK_SKEW = 30

    def __init__(self, signing_key: bytes, allowed_issuers: list):
        if not signing_key or len(signing_key) < 32:
            raise ValueError("Signing key must be at least 32 bytes")
        self._signing_key = signing_key
        self._allowed_issuers = frozenset(allowed_issuers)
        self._revocation_set: set = set()

    def _safe_b64decode(self, data: str) -> bytes:
        """URL-safe base64 decode with padding normalization and strict validation."""
        # Add padding if necessary
        padded = data + '=' * (4 - len(data) % 4) if len(data) % 4 else data
        try:
            # validate=True rejects any non-alphabet characters, preventing
            # token malleability (distinct inputs decoding to identical bytes).
            return base64.urlsafe_b64decode(padded.encode('ascii'))
        except Exception:
            return b''

    def _split_token(self, token: str) -> Tuple[str, str, str]:
        """Split token into header, payload, signature parts."""
        parts = token.split('.')
        if len(parts) != 3:
            raise ValueError("Malformed token structure")
        return parts[0], parts[1], parts[2]

    def _compute_signature(self, algorithm: str, signing_input: str) -> bytes:
        """Compute HMAC signature over the signing input."""
        hash_func = self.HASH_MAP.get(algorithm)
        if hash_func is None:
            raise ValueError(f"Unsupported algorithm: {algorithm}")
        return hmac.new(
            self._signing_key,
            signing_input.encode('utf-8'),
            hash_func
        ).digest()

    def _verify_signature(self, algorithm: str, signing_input: str, signature: bytes) -> bool:
        """Constant-time signature verification with length pre-check."""
        expected = self._compute_signature(algorithm, signing_input)
        # Ensure signature has correct length for the algorithm
        if len(signature) != len(expected):
            return False
        return hmac.compare_digest(expected, signature)

    def _validate_header(self, header_raw: str) -> Dict[str, Any]:
        """Validate and parse the token header."""
        header_bytes = self._safe_b64decode(header_raw)
        if not header_bytes:
            raise ValueError("Invalid header encoding")
        header = json.loads(header_bytes)
        if not isinstance(header, dict):
            raise ValueError("Header must be a JSON object")
        alg = header.get('alg')
        if alg not in self.SUPPORTED_ALGORITHMS:
            raise ValueError(f"Algorithm not allowed: {alg}")
        typ = header.get('typ', 'JWT')
        if typ != 'JWT':
            raise ValueError(f"Unsupported token type: {typ}")
        return header

    def _validate_claims(self, payload: Dict[str, Any]) -> None:
        """Validate standard JWT claims."""
        now = time.time()

        # Check expiration
        exp = payload.get('exp')
        if exp is None:
            raise ValueError("Token missing expiration claim")
        if not isinstance(exp, (int, float)):
            raise ValueError("Invalid expiration type")
        if now > exp + self.MAX_CLOCK_SKEW:
            raise ValueError("Token has expired")

        # Check not-before
        nbf = payload.get('nbf')
        if nbf is not None:
            if not isinstance(nbf, (int, float)):
                raise ValueError("Invalid nbf type")
            if now < nbf - self.MAX_CLOCK_SKEW:
                raise ValueError("Token not yet valid")

        # Check issued-at for max age
        iat = payload.get('iat')
        if iat is not None:
            if not isinstance(iat, (int, float)):
                raise ValueError("Invalid iat type")
            if now - iat > self.MAX_TOKEN_AGE:
                raise ValueError("Token exceeds maximum age")

        # Check issuer
        iss = payload.get('iss')
        if iss is None:
            raise ValueError("Token missing issuer claim")
        if iss not in self._allowed_issuers:
            raise ValueError(f"Untrusted issuer: {iss}")

        # Check subject
        sub = payload.get('sub')
        if sub is None or not isinstance(sub, str) or len(sub) == 0:
            raise ValueError("Token missing or invalid subject")

        # Check token ID for revocation
        jti = payload.get('jti')
        if jti and jti in self._revocation_set:
            raise ValueError("Token has been revoked")

    def validate_token(self, token: str) -> Optional[Dict[str, Any]]:
        """Validate a JWT token and return its claims if valid.

        Returns None on any validation failure (generic error to caller).
        """
        try:
            if not isinstance(token, str) or len(token) > 8192:
                return None

            # Split token
            header_raw, payload_raw, signature_raw = self._split_token(token)

            # Validate header first to get algorithm
            header = self._validate_header(header_raw)
            algorithm = header['alg']

            # Decode signature
            signature = self._safe_b64decode(signature_raw)

            # Reject empty signatures immediately
            if not signature:
                return None

            # Verify signature (constant-time comparison)
            signing_input = f"{header_raw}.{payload_raw}"
            if not self._verify_signature(algorithm, signing_input, signature):
                return None

            # Decode and validate payload
            payload_bytes = self._safe_b64decode(payload_raw)
            if not payload_bytes:
                return None
            payload = json.loads(payload_bytes)
            if not isinstance(payload, dict):
                return None

            # Validate claims
            self._validate_claims(payload)

            return payload

        except (ValueError, json.JSONDecodeError, KeyError, TypeError):
            return None

    def revoke_token(self, jti: str) -> None:
        """Add a token ID to the revocation set."""
        if isinstance(jti, str) and len(jti) <= 128:
            self._revocation_set.add(jti)


# Application entry point
def create_validator() -> SecureTokenValidator:
    key = os.environ.get('JWT_SIGNING_KEY', '').encode('utf-8')
    issuers = os.environ.get('ALLOWED_ISSUERS', 'auth.internal').split(',')
    return SecureTokenValidator(key, issuers)


def handle_request(token: str) -> Tuple[int, Dict[str, Any]]:
    """Handle an authentication request."""
    validator = create_validator()
    claims = validator.validate_token(token)
    if claims is None:
        return 401, {"error": "authentication_failed"}
    return 200, {"user": claims.get('sub'), "scope": claims.get('scope', [])}
